import { createHmac } from "node:crypto";
import { createServer, type Server } from "node:http";
import {
  afterAll,
  afterEach,
  beforeAll,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import {
  generateAuthSessionCookie,
  putAttachment,
  verifyAuthSessionValue,
} from "./couchdb";

// Independent Node crypto fixture, not generated by the function under test.
const secret = "fixture-secret";
const salt = "00112233445566778899aabbccddeeff";
const expires = 2_000_000_000;
const signed = (algorithm: "sha1" | "sha256", mac?: Buffer) => {
  const message = `fixture-user:${expires.toString(16).toUpperCase()}`;
  const signature =
    mac ??
    createHmac(
      algorithm,
      Buffer.concat([Buffer.from(secret), Buffer.from(salt, "hex")]),
    )
      .update(message)
      .digest();
  return Buffer.concat([Buffer.from(`${message}:`), signature]).toString(
    "base64url",
  );
};
afterEach(() => vi.restoreAllMocks());
describe("session helper typing preserves wire behavior", () => {
  it("generates the existing SHA-1 cookie bytes and flags", () => {
    vi.spyOn(Date, "now").mockReturnValue(1_900_000_000_000);
    const message = `fixture-user:${(1_900_000_000 + 600).toString(16).toUpperCase()}`;
    const mac = createHmac("sha1", "fixture-secretfixture-salt")
      .update(message)
      .digest();
    const token = Buffer.concat([Buffer.from(`${message}:`), mac]).toString(
      "base64url",
    );
    expect(
      generateAuthSessionCookie("fixture-user", secret, "fixture-salt"),
    ).toBe(
      `AuthSession=${token}; Version=1; Path=/; HttpOnly${process.env.NODE_ENV === "production" ? "; Secure" : ""}`,
    );
  });
  for (const algorithm of ["sha1", "sha256"] as const) {
    it(`verifies ${algorithm} with numeric and Date timestamps`, () => {
      for (const now of [1_999_999_999_000, new Date(1_999_999_999_000)]) {
        expect(
          verifyAuthSessionValue({
            value: signed(algorithm),
            serverSecret: secret,
            userSaltHex: salt,
            now,
          }),
        ).toEqual({ ok: true, username: "fixture-user", exp: expires });
      }
    });
  }
  it("rejects expired dates, mismatching bytes and mismatching MAC lengths", () => {
    expect(
      verifyAuthSessionValue({
        value: signed("sha256"),
        serverSecret: secret,
        userSaltHex: salt,
        now: new Date(2_000_000_001_000),
      }),
    ).toMatchObject({ ok: false, reason: "expired" });
    for (const mac of [Buffer.alloc(32), Buffer.alloc(1)]) {
      expect(
        verifyAuthSessionValue({
          value: signed("sha256", mac),
          serverSecret: secret,
          userSaltHex: salt,
        }),
      ).toEqual({ ok: false, reason: "HMAC mismatch" });
    }
    expect(
      verifyAuthSessionValue({
        value: null,
        serverSecret: secret,
        userSaltHex: salt,
      }),
    ).toEqual({ ok: false, reason: "missing value" });
  });
});
describe("attachment binary request bodies", () => {
  let server: Server;
  let baseUrl: string;
  let received: {
    bytes: number[];
    url: string;
    contentType: string | undefined;
  };
  beforeAll(async () => {
    server = createServer(async (req, res) => {
      const chunks: Buffer[] = [];
      for await (const chunk of req) chunks.push(Buffer.from(chunk));
      received = {
        bytes: [...Buffer.concat(chunks)],
        url: req.url!,
        contentType: req.headers["content-type"],
      };
      res.writeHead(201, { "content-type": "application/json" });
      res.end(JSON.stringify({ ok: true, id: "doc", rev: "2-next" }));
    });
    await new Promise<void>((resolve) =>
      server.listen(0, "127.0.0.1", resolve),
    );
    const address = server.address();
    if (!address || typeof address === "string")
      throw new Error("Missing fixture port");
    baseUrl = `http://127.0.0.1:${address.port}`;
  });
  afterAll(async () => {
    await new Promise<void>((resolve, reject) =>
      server.close((e) => (e ? reject(e) : resolve())),
    );
  });
  const bytes = [0, 255, 127, 128];
  const backing = Uint8Array.from([99, ...bytes, 88]);
  const shared = new Uint8Array(new SharedArrayBuffer(6));
  shared.set([99, ...bytes, 88]);
  const cases: [string, Buffer | Uint8Array | string][] = [
    ["Buffer subarray", Buffer.from([99, ...bytes, 88]).subarray(1, 5)],
    ["Uint8Array subarray", backing.subarray(1, 5)],
    ["SharedArrayBuffer view", shared.subarray(1, 5)],
    ["base64 string", "AP9/gA=="],
  ];
  it.each(cases)(
    "uploads exactly the selected bytes from a %s",
    async (_label, data) => {
      expect(
        await putAttachment(
          "fixture",
          "doc/id",
          "a b.bin",
          data,
          "application/octet-stream",
          "1-old",
          { baseUrl, adminAuth: "Zml4dHVyZTpmaXh0dXJl" },
        ),
      ).toEqual({ ok: true, id: "doc", rev: "2-next" });
      expect(received).toEqual({
        bytes: [0, 255, 127, 128],
        url: "/fixture/doc%2Fid/a%20b.bin?rev=1-old",
        contentType: "application/octet-stream",
      });
    },
  );
});
